    ans = [-1] * N

    h = []
    for a in A:
        if a <= N:
            top[a] = -1
        else:
            heapq.heappush(h, -a)

    i = 1
    for m in range(M):
        if not top[N + 1]:
            ans[i] = m + 1
            i += 1
        elif top[N + 1] > -h[0]:
            ans[i] = h[0]
            i += 1
            heapq.heappop(h)
        else:
            ans[i] = -1
            i += 1

    print(' '.join(map(str, ans))

